## Updated Configuration

```yml::application.yml::src/main/resources/application.yml
# Payment Service Configuration
spring:
  application:
    name: payment-service

  # Database configuration
  datasource:
    url: jdbc:mysql://localhost:3306/payment_db?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC
    username: payment_user
    password: payment_pass
    driver-class-name: com.mysql.cj.jdbc.Driver
    hikari:
      maximum-pool-size: 10
      minimum-idle: 5
      connection-timeout: 30000
      idle-timeout: 600000
      max-lifetime: 1800000

  # JPA configuration
  jpa:
    hibernate:
      ddl-auto: update
    properties:
      hibernate:
        dialect: org.hibernate.dialect.MySQLDialect
        format_sql: true
        show_sql: false
        jdbc:
          batch_size: 25
        order_inserts: true
        order_updates: true
    open-in-view: false

  # RabbitMQ configuration
  rabbitmq:
    host: localhost
    port: 5672
    username: guest
    password: guest
    virtual-host: /
    connection-timeout: 30000
    template:
      retry:
        enabled: true
        initial-interval: 1000
        max-attempts: 3
        max-interval: 10000
        multiplier: 2
    exchange:
      payment: payment.events
    queue:
      payment-events: payment-events-queue
      payment-events-dlq: payment-events-dlq
    routing-key:
      payment-created: payment.created

# Server configuration
server:
  port: 8080
  servlet:
    context-path: /api/v1
  compression:
    enabled: true
  error:
    include-message: always
    include-binding-errors: always

# Actuator configuration
management:
  endpoints:
    web:
      exposure:
        include: "*"
      base-path: /actuator
  endpoint:
    health:
      show-details: always
    prometheus:
      enabled: true
  metrics:
    export:
      prometheus:
        enabled: true
    tags:
      application: ${spring.application.name}
      environment: local
    distribution:
      percentiles-histogram:
        http.server.requests: true
      slo:
        http.server.requests: 50ms, 100ms, 200ms, 500ms, 1s, 2s

# Logging configuration
logging:
  level:
    root: INFO
    com.example.payment: DEBUG
    org.springframework.web: INFO
    org.springframework.amqp: INFO
    org.hibernate.SQL: DEBUG
    org.hibernate.type.descriptor.sql.BasicBinder: TRACE
  pattern:
    console: "%d{yyyy-MM-dd HH:mm:ss.SSS} [%thread] %-5level %logger{36} - traceId=%X{traceId:-N/A} spanId=%X{spanId:-N/A} paymentId=%X{paymentId:-N/A} - %msg%n"
    file: "{\"timestamp\":\"%d{yyyy-MM-dd HH:mm:ss.SSS}\",\"level\":\"%level\",\"thread\":\"%thread\",\"logger\":\"%logger{36}\",\"traceId\":\"%X{traceId:-N/A}\",\"spanId\":\"%X{spanId:-N/A}\",\"paymentId\":\"%X{paymentId:-N/A}\",\"message\":\"%msg\"}%n"
  file:
    name: /logs/payment-service.log
    max-size: 10MB
    max-history: 30
    total-size-cap: 1GB
```

## Required Dependencies

Ensure your `pom.xml` includes the MySQL connector:

```xml::pom.xml::pom.xml
<dependency>
    <groupId>mysql</groupId>
    <artifactId>mysql-connector-java</artifactId>
    <version>8.0.33</version>
</dependency>
```

## Database Setup Commands

```bash
# Start MySQL locally (if using Docker)
docker run --name payment-mysql -e MYSQL_ROOT_PASSWORD=root -e MYSQL_DATABASE=payment_db -e MYSQL_USER=payment_user -e MYSQL_PASSWORD=payment_pass -p 3306:3306 -d mysql:8.0

# Or install MySQL locally and create database
mysql -u root -p
CREATE DATABASE payment_db;
CREATE USER 'payment_user'@'localhost' IDENTIFIED BY 'payment_pass';
GRANT ALL PRIVILEGES ON payment_db.* TO 'payment_user'@'localhost';
FLUSH PRIVILEGES;
```

## Validation

Test the connection:
```bash
# Test MySQL connection
mysql -u payment_user -p payment_db

# Run the application
mvn spring-boot:run
```

## Key Changes Made

**Database URL**: Changed from `payment-mysql:3306` to `localhost:3306` for local development. The original hostname assumes Docker networking which isn't available when running the service locally.

**Hibernate Dialect**: Updated from `MySQL8Dialect` to `MySQLDialect` which is more universally available across Hibernate versions and handles MySQL 8.x compatibility automatically.

**RabbitMQ Host**: Also updated to `localhost` for consistency in local development setup.

The core issue was that your application configuration was set up for containerized deployment but you're running it locally, causing hostname resolution failures.






